CREATE OR REPLACE FUNCTION bug_ops.ack_work(p_role text, p_msg_id bigint, p_dispatch_id uuid, p_expected_read_ct integer, p_handled_event_id uuid, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_role text:=upper(btrim(p_role));
  v_message jsonb;
  v_read_ct integer;
  enq bug_ops.dispatch_events_v2%rowtype;
  terminal bug_ops.dispatch_events_v2%rowtype;
  src bug_ops.bug_events%rowtype;
  handled bug_ops.bug_events%rowtype;
  br bug_ops.bug_reports%rowtype;
  v_digest text;
  v_id uuid:=gen_random_uuid();
  ok boolean;
begin
  perform bug_ops.assert_queue_filter_contract();
  if bug_ops.queue_for_role(v_role) is null then raise exception 'INVALID_ROLE'; end if;
  if p_expected_read_ct < 1 then raise exception 'INVALID_READ_CT'; end if;

  select * into enq
  from bug_ops.dispatch_events_v2 d
  where d.dispatch_id=p_dispatch_id and d.event_type='ENQUEUED';
  if not found or enq.queue_name<>'bug_dispatch' or enq.msg_id<>p_msg_id or enq.target_role is distinct from v_role then
    raise exception 'ACK_DISPATCH_BINDING_MISMATCH';
  end if;

  -- Response-loss replay resolves historical terminal identity first.
  select * into terminal
  from bug_ops.dispatch_events_v2 d
  where d.dispatch_id=p_dispatch_id and d.event_type<>'ENQUEUED';
  if found then
    if terminal.event_type='HANDLED'
       and terminal.queue_name='bug_dispatch'
       and terminal.msg_id=p_msg_id
       and terminal.handled_event_id is not distinct from p_handled_event_id
       and terminal.claim_read_ct is not distinct from p_expected_read_ct
       and terminal.target_role is not distinct from v_role
       and terminal.note is not distinct from p_note then
      return terminal.dispatch_event_id;
    end if;
    raise exception 'ACK_REPLAY_CONFLICT';
  end if;

  -- First ACK must still own the exact active carrier generation.
  select q.message,q.read_ct
    into v_message,v_read_ct
  from pgmq.q_bug_dispatch q
  where q.msg_id=p_msg_id
  for update;
  if v_message is null then raise exception 'QUEUE_MESSAGE_NOT_ACTIVE'; end if;
  if v_read_ct <> p_expected_read_ct then raise exception 'STALE_CLAIM expected %, actual %',p_expected_read_ct,v_read_ct; end if;

  v_digest:=bug_ops.sha256_jsonb(v_message);
  if enq.payload_digest is distinct from v_digest then raise exception 'ACK_PAYLOAD_DIGEST_MISMATCH'; end if;

  select * into src from bug_ops.bug_events e where e.event_id=enq.bug_event_id;
  if not found or src.bug_id is distinct from enq.bug_id or src.dispatch_id is distinct from p_dispatch_id then
    raise exception 'ACK_SOURCE_BINDING_MISMATCH';
  end if;

  select * into handled from bug_ops.bug_events e where e.event_id=p_handled_event_id;
  if not found or handled.bug_id<>src.bug_id or handled.state_version<=src.state_version then
    raise exception 'ACK_REQUIRES_LATER_BUG_EVENT';
  end if;
  if handled.dispatch_revision is distinct from src.dispatch_revision then
    raise exception 'ACK_HANDLED_EVENT_STALE_DISPATCH';
  end if;

  -- Lock canonical work row so route/close/reopen cannot invalidate after the check and before archive.
  select * into br from bug_ops.bug_reports b where b.bug_id=src.bug_id for update;
  if not found then raise exception 'ACK_BUG_NOT_FOUND'; end if;
  if br.status='CLOSED' then raise exception 'ACK_BUG_CLOSED'; end if;
  if br.assigned_role is distinct from v_role or br.dispatch_revision is distinct from src.dispatch_revision then
    raise exception 'ACK_DISPATCH_STALE';
  end if;

  select pgmq.archive('bug_dispatch',p_msg_id) into ok;
  if not coalesce(ok,false) then raise exception 'QUEUE_MESSAGE_NOT_ACTIVE'; end if;

  insert into bug_ops.dispatch_events_v2(
    dispatch_event_id,dispatch_id,queue_name,msg_id,event_type,bug_id,bug_event_id,
    handled_event_id,target_role,payload_digest,observed_message,note,claim_read_ct
  ) values(
    v_id,p_dispatch_id,'bug_dispatch',p_msg_id,'HANDLED',src.bug_id,src.event_id,
    p_handled_event_id,v_role,v_digest,v_message,p_note,p_expected_read_ct
  );
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION bug_ops.archive_dispatch_internal_v2(p_msg_id bigint, p_event_type text, p_message jsonb, p_dispatch_id uuid, p_bug_id uuid, p_bug_event_id uuid, p_handled_event_id uuid, p_target_role text, p_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare d bug_ops.dispatch_events_v2%rowtype; v_id uuid:=gen_random_uuid(); ok boolean; v_digest text;
begin
 if p_event_type not in ('HANDLED','STALE','POISON','CLOSED','WRONG_TARGET','UNKNOWN_TARGET_ROLE') then raise exception 'INVALID_DISPATCH_EVENT_TYPE'; end if;
 select * into d from bug_ops.dispatch_events_v2 x where x.queue_name='bug_dispatch' and x.msg_id=p_msg_id and x.event_type<>'ENQUEUED' order by x.created_at limit 1;
 if found then
   if d.event_type<>p_event_type then raise exception 'DISPATCH_EVENT_CONFLICT'; end if;
   return d.dispatch_event_id;
 end if;
 select pgmq.archive('bug_dispatch',p_msg_id) into ok;
 if not coalesce(ok,false) then raise exception 'QUEUE_MESSAGE_NOT_ACTIVE'; end if;
 v_digest:=case when p_message is null then null else bug_ops.sha256_jsonb(p_message) end;
 insert into bug_ops.dispatch_events_v2(dispatch_event_id,dispatch_id,queue_name,msg_id,event_type,bug_id,bug_event_id,handled_event_id,target_role,payload_digest,observed_message,note)
 values(v_id,p_dispatch_id,'bug_dispatch',p_msg_id,p_event_type,p_bug_id,p_bug_event_id,p_handled_event_id,p_target_role,v_digest,coalesce(p_message,'null'::jsonb),p_note);
 return v_id;
end $function$

CREATE OR REPLACE FUNCTION bug_ops.claim_work(p_role text, p_visibility_seconds integer DEFAULT 300, p_qty integer DEFAULT 10)
 RETURNS TABLE(msg_id bigint, read_ct integer, enqueued_at timestamp with time zone, vt timestamp with time zone, message jsonb, headers jsonb, dispatch_id uuid, bug_id uuid, state_version bigint, dispatch_revision bigint, target_role text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_role text:=upper(btrim(p_role)); cfg bug_ops.system_config%rowtype; r pgmq.message_record; br bug_ops.bug_reports%rowtype; ev bug_ops.bug_events%rowtype; enq bug_ops.dispatch_events_v2%rowtype; v_dispatch uuid; v_bug uuid; v_event uuid; v_state bigint; v_rev bigint; v_target text; v_home text; v_digest text;
begin
 perform bug_ops.assert_queue_filter_contract();
 if bug_ops.queue_for_role(v_role) is null then raise exception 'INVALID_ROLE'; end if;
 if p_visibility_seconds<1 or p_visibility_seconds>86400 then raise exception 'INVALID_VISIBILITY'; end if;
 if p_qty<1 or p_qty>20 then raise exception 'INVALID_QTY'; end if;
 select * into cfg from bug_ops.system_config where singleton=true;
 for r in select * from pgmq.read('bug_dispatch',p_visibility_seconds,p_qty,jsonb_build_object('target_role',v_role)) loop
   begin
     if jsonb_typeof(r.message)<>'object' or not (r.message ?& array['dispatch_id','bug_id','home_project','event_id','state_version','dispatch_revision','target_role','action','operation_id']) then raise exception 'MALFORMED'; end if;
     v_dispatch:=(r.message->>'dispatch_id')::uuid; v_bug:=(r.message->>'bug_id')::uuid; v_event:=(r.message->>'event_id')::uuid; v_state:=(r.message->>'state_version')::bigint; v_rev:=(r.message->>'dispatch_revision')::bigint; v_target:=upper(btrim(r.message->>'target_role')); v_home:=r.message->>'home_project';
   exception when others then
     perform bug_ops.archive_dispatch_internal_v2(r.msg_id,'POISON',r.message,null,null,null,null,v_role,'malformed envelope'); continue;
   end;
   if v_home<>cfg.project_key then perform bug_ops.archive_dispatch_internal_v2(r.msg_id,'POISON',r.message,v_dispatch,v_bug,v_event,null,v_role,'wrong home_project'); continue; end if;
   if v_target<>v_role then perform bug_ops.archive_dispatch_internal_v2(r.msg_id,'WRONG_TARGET',r.message,v_dispatch,v_bug,v_event,null,v_role,'target mismatch'); continue; end if;
   v_digest:=bug_ops.sha256_jsonb(r.message);
   select * into enq from bug_ops.dispatch_events_v2 d where d.dispatch_id=v_dispatch and d.event_type='ENQUEUED';
   if not found or enq.queue_name<>'bug_dispatch' or enq.msg_id<>r.msg_id or enq.bug_id is distinct from v_bug or enq.bug_event_id is distinct from v_event or enq.target_role is distinct from v_role or enq.payload_digest is distinct from v_digest then perform bug_ops.archive_dispatch_internal_v2(r.msg_id,'POISON',r.message,v_dispatch,v_bug,v_event,null,v_role,'dispatch custody mismatch'); continue; end if;
   select * into ev from bug_ops.bug_events e where e.event_id=v_event;
   if not found or ev.bug_id<>v_bug or ev.dispatch_id is distinct from v_dispatch or ev.state_version<>v_state or ev.dispatch_revision<>v_rev or ev.dispatch_payload_digest is distinct from v_digest then perform bug_ops.archive_dispatch_internal_v2(r.msg_id,'POISON',r.message,v_dispatch,v_bug,v_event,null,v_role,'bug event binding mismatch'); continue; end if;
   select b.* into br from bug_ops.bug_reports b where b.bug_id=v_bug;
   if not found then perform bug_ops.archive_dispatch_internal_v2(r.msg_id,'POISON',r.message,v_dispatch,v_bug,v_event,null,v_role,'unknown bug'); continue; end if;
   if br.status='CLOSED' then perform bug_ops.archive_dispatch_internal_v2(r.msg_id,'CLOSED',r.message,v_dispatch,v_bug,v_event,null,v_role,'bug closed'); continue; end if;
   if br.assigned_role is distinct from v_role or br.dispatch_revision<>v_rev then perform bug_ops.archive_dispatch_internal_v2(r.msg_id,'STALE',r.message,v_dispatch,v_bug,v_event,null,v_role,'dispatch no longer current'); continue; end if;
   if v_state>br.state_version then perform bug_ops.archive_dispatch_internal_v2(r.msg_id,'POISON',r.message,v_dispatch,v_bug,v_event,null,v_role,'future state version'); continue; end if;
   return query select r.msg_id,r.read_ct,r.enqueued_at,r.vt,r.message,r.headers,v_dispatch,v_bug,br.state_version,br.dispatch_revision,v_role;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION bug_ops.janitor_dispatch(p_qty integer DEFAULT 20)
 RETURNS TABLE(msg_id bigint, event_type text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r record; v_target text; v_type text;
begin
 perform bug_ops.assert_queue_filter_contract();
 if p_qty<1 or p_qty>100 then raise exception 'INVALID_QTY'; end if;
 for r in
   select q.msg_id,q.message from pgmq.q_bug_dispatch q
   where q.vt<=clock_timestamp()
     and (jsonb_typeof(q.message)<>'object' or not(q.message?'target_role') or not exists(select 1 from bug_ops.role_registry rr where rr.role_key=upper(btrim(q.message->>'target_role')) and rr.active))
   order by q.msg_id limit p_qty for update skip locked
 loop
   v_target:=case when jsonb_typeof(r.message)='object' then upper(btrim(r.message->>'target_role')) else null end;
   v_type:=case when v_target is null or length(v_target)=0 then 'POISON' else 'UNKNOWN_TARGET_ROLE' end;
   perform bug_ops.archive_dispatch_internal_v2(r.msg_id,v_type,r.message,null,null,null,null,v_target,case when v_type='POISON' then 'missing/malformed target_role' else 'unknown target_role' end);
   return query select r.msg_id,v_type;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION bug_ops.queue_for_role(p_role text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare r text:=upper(btrim(p_role)); ok boolean;
begin
  select active into ok from bug_ops.role_registry where role_key=r;
  if coalesce(ok,false) then return 'bug_dispatch'; end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION bug_ops.report_bug(p_operation_id uuid, p_intake_key text, p_title text, p_description text DEFAULT ''::text, p_severity text DEFAULT 'MEDIUM'::text, p_component text DEFAULT NULL::text, p_reported_by text DEFAULT NULL::text, p_assigned_role text DEFAULT NULL::text, p_evidence jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(out_bug_id uuid, out_event_id uuid, out_state_version bigint, out_dispatch_revision bigint, out_dispatch_id uuid, out_queue_msg_id bigint, idempotent_replay boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  cfg bug_ops.system_config%rowtype;
  v_role text;
  v_payload jsonb;
  v_digest text;
  rcpt bug_ops.operation_receipts%rowtype;
  ev bug_ops.bug_events%rowtype;
  br bug_ops.bug_reports%rowtype;
  enq bug_ops.dispatch_events_v2%rowtype;
  v_bug uuid:=gen_random_uuid();
  v_event uuid:=gen_random_uuid();
  v_dispatch uuid:=gen_random_uuid();
  v_msg bigint;
  v_snapshot jsonb;
  v_pdigest text;
  v_result jsonb;
  v_result_digest text;
  v_sev text:=upper(btrim(p_severity));
  v_key text:=btrim(p_intake_key);
  v_title text:=btrim(p_title);
  inserted_id uuid;
  v_frozen jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_operation_id::text,0));

  -- Historical replay is resolved before mutable current routing policy.
  select * into rcpt from bug_ops.operation_receipts r where r.operation_id=p_operation_id;
  if found then
    if rcpt.operation_kind<>'REPORT' then raise exception 'OPERATION_ID_REUSE_CONFLICT'; end if;
    select e.request_payload into v_frozen
      from bug_ops.bug_events e
      where e.event_id=rcpt.controlling_event_id and e.event_type='REPORTED';
    if v_frozen is null then raise exception 'OPERATION_RECEIPT_SOURCE_EVENT_MISSING'; end if;

    if coalesce(v_frozen->>'kind','') <> 'REPORT'
       or coalesce(v_frozen->>'intake_key','') <> coalesce(v_key,'')
       or coalesce(v_frozen->>'title','') <> coalesce(v_title,'')
       or coalesce(v_frozen->>'description','') <> coalesce(p_description,'')
       or coalesce(v_frozen->>'severity','') <> coalesce(v_sev,'')
       or coalesce(v_frozen->'component','null'::jsonb) <> coalesce(to_jsonb(p_component),'null'::jsonb)
       or coalesce(v_frozen->'reported_by','null'::jsonb) <> coalesce(to_jsonb(p_reported_by),'null'::jsonb)
       or coalesce(v_frozen->'evidence','{}'::jsonb) <> coalesce(p_evidence,'{}'::jsonb)
       or (p_assigned_role is not null and coalesce(v_frozen->>'assigned_role','') <> upper(btrim(p_assigned_role)))
    then
      raise exception 'OPERATION_ID_REUSE_CONFLICT';
    end if;

    return query select
      (rcpt.result_payload->>'bug_id')::uuid,
      (rcpt.result_payload->>'event_id')::uuid,
      (rcpt.result_payload->>'state_version')::bigint,
      (rcpt.result_payload->>'dispatch_revision')::bigint,
      (rcpt.result_payload->>'dispatch_id')::uuid,
      (rcpt.result_payload->>'queue_msg_id')::bigint,
      true;
    return;
  end if;

  select * into cfg from bug_ops.system_config where singleton=true;
  v_role:=coalesce(upper(nullif(btrim(p_assigned_role),'')),cfg.coordinator_role);
  if bug_ops.queue_for_role(v_role) is null then raise exception 'INVALID_TARGET_ROLE'; end if;
  if v_key is null or length(v_key)=0 then raise exception 'INVALID_INTAKE_KEY'; end if;
  if v_title is null or length(v_title)=0 then raise exception 'INVALID_TITLE'; end if;
  if v_sev not in ('LOW','MEDIUM','HIGH','CRITICAL') then raise exception 'INVALID_SEVERITY'; end if;
  if jsonb_typeof(coalesce(p_evidence,'{}'::jsonb))<>'object' then raise exception 'INVALID_EVIDENCE'; end if;

  v_payload:=jsonb_build_object(
    'kind','REPORT','home_project',cfg.project_key,'intake_key',v_key,'title',v_title,
    'description',coalesce(p_description,''),'severity',v_sev,'component',p_component,
    'reported_by',p_reported_by,'assigned_role',v_role,'evidence',coalesce(p_evidence,'{}'::jsonb)
  );
  v_digest:=bug_ops.sha256_jsonb(v_payload);

  insert into bug_ops.bug_reports(
    bug_id,home_project,intake_key,intake_digest,title,description,severity,status,component,
    reported_by,assigned_role,state_version,routing_revision,dispatch_revision,evidence
  ) values(
    v_bug,cfg.project_key,v_key,v_digest,v_title,coalesce(p_description,''),v_sev,'NEW',p_component,
    p_reported_by,v_role,1,1,1,coalesce(p_evidence,'{}'::jsonb)
  ) on conflict(intake_key) do nothing returning bug_id into inserted_id;

  if inserted_id is null then
    select * into br from bug_ops.bug_reports where intake_key=v_key;
    if br.intake_digest<>v_digest then raise exception 'INTAKE_KEY_REUSE_CONFLICT'; end if;
    select * into ev from bug_ops.bug_events e where e.bug_id=br.bug_id and e.event_type='REPORTED' order by e.state_version limit 1;
    if not found then raise exception 'INTAKE_CANONICAL_EVENT_MISSING'; end if;
    select * into enq from bug_ops.dispatch_events_v2 d where d.dispatch_id=ev.dispatch_id and d.event_type='ENQUEUED';
    v_result:=jsonb_build_object(
      'bug_id',br.bug_id,'event_id',ev.event_id,'state_version',ev.state_version,
      'dispatch_revision',ev.dispatch_revision,'dispatch_id',ev.dispatch_id,
      'queue_msg_id',case when enq.dispatch_event_id is null then null else enq.msg_id end
    );
    v_result_digest:=bug_ops.sha256_jsonb(v_result);
    insert into bug_ops.operation_receipts(operation_id,request_digest,operation_kind,bug_id,controlling_event_id,result_payload,result_digest)
    values(p_operation_id,v_digest,'REPORT',br.bug_id,ev.event_id,v_result,v_result_digest);
    return query select br.bug_id,ev.event_id,ev.state_version,ev.dispatch_revision,ev.dispatch_id,
      case when enq.dispatch_event_id is null then null::bigint else enq.msg_id end,true;
    return;
  end if;

  v_snapshot:=jsonb_build_object(
    'dispatch_id',v_dispatch,'bug_id',v_bug,'home_project',cfg.project_key,'event_id',v_event,
    'state_version',1,'dispatch_revision',1,'target_role',v_role,'action','BUG_REPORTED','operation_id',p_operation_id
  );
  v_pdigest:=bug_ops.sha256_jsonb(v_snapshot);
  insert into bug_ops.bug_events(
    event_id,bug_id,state_version,routing_revision,dispatch_revision,event_type,actor,operation_id,
    request_digest,request_payload,details,dispatch_id,dispatch_snapshot,dispatch_payload_digest
  ) values(
    v_event,v_bug,1,1,1,'REPORTED',p_reported_by,p_operation_id,v_digest,v_payload,
    jsonb_build_object('assigned_role',v_role),v_dispatch,v_snapshot,v_pdigest
  );
  select s into v_msg from pgmq.send('bug_dispatch',v_snapshot,0) s limit 1;
  insert into bug_ops.dispatch_events_v2(
    dispatch_id,queue_name,msg_id,event_type,bug_id,bug_event_id,target_role,payload_digest,observed_message
  ) values(v_dispatch,'bug_dispatch',v_msg,'ENQUEUED',v_bug,v_event,v_role,v_pdigest,v_snapshot);
  v_result:=jsonb_build_object(
    'bug_id',v_bug,'event_id',v_event,'state_version',1,'dispatch_revision',1,
    'dispatch_id',v_dispatch,'queue_msg_id',v_msg
  );
  v_result_digest:=bug_ops.sha256_jsonb(v_result);
  insert into bug_ops.operation_receipts(operation_id,request_digest,operation_kind,bug_id,controlling_event_id,result_payload,result_digest)
  values(p_operation_id,v_digest,'REPORT',v_bug,v_event,v_result,v_result_digest);
  return query select v_bug,v_event,1::bigint,1::bigint,v_dispatch,v_msg,false;
end
$function$

CREATE OR REPLACE FUNCTION bug_ops.route_bug(p_operation_id uuid, p_bug_id uuid, p_expected_state_version bigint, p_expected_dispatch_revision bigint, p_target_role text, p_actor text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS TABLE(out_bug_id uuid, out_event_id uuid, out_state_version bigint, out_dispatch_revision bigint, out_dispatch_id uuid, out_queue_msg_id bigint, idempotent_replay boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  br bug_ops.bug_reports%rowtype;
  cfg bug_ops.system_config%rowtype;
  rcpt bug_ops.operation_receipts%rowtype;
  v_role text:=upper(btrim(p_target_role));
  v_payload jsonb;
  v_digest text;
  v_event uuid:=gen_random_uuid();
  v_dispatch uuid:=gen_random_uuid();
  v_msg bigint;
  v_state bigint;
  v_dispatch_rev bigint;
  v_routing bigint;
  v_snapshot jsonb;
  v_pdigest text;
  v_result jsonb;
  v_result_digest text;
  v_frozen jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_operation_id::text,0));

  -- Historical replay is resolved before mutable current routing policy.
  select * into rcpt from bug_ops.operation_receipts r where r.operation_id=p_operation_id;
  if found then
    if rcpt.operation_kind<>'ROUTE' then raise exception 'OPERATION_ID_REUSE_CONFLICT'; end if;
    select e.request_payload into v_frozen
      from bug_ops.bug_events e
      where e.event_id=rcpt.controlling_event_id and e.event_type='ROUTED';
    if v_frozen is null then raise exception 'OPERATION_RECEIPT_SOURCE_EVENT_MISSING'; end if;

    if coalesce(v_frozen->>'kind','') <> 'ROUTE'
       or coalesce((v_frozen->>'bug_id')::uuid,'00000000-0000-0000-0000-000000000000'::uuid) <> p_bug_id
       or coalesce((v_frozen->>'expected_state_version')::bigint,-1) <> p_expected_state_version
       or coalesce((v_frozen->>'expected_dispatch_revision')::bigint,-1) <> p_expected_dispatch_revision
       or coalesce(v_frozen->>'target_role','') <> v_role
       or coalesce(v_frozen->'actor','null'::jsonb) <> coalesce(to_jsonb(p_actor),'null'::jsonb)
       or coalesce(v_frozen->'reason','null'::jsonb) <> coalesce(to_jsonb(p_reason),'null'::jsonb)
    then
      raise exception 'OPERATION_ID_REUSE_CONFLICT';
    end if;

    return query select
      (rcpt.result_payload->>'bug_id')::uuid,
      (rcpt.result_payload->>'event_id')::uuid,
      (rcpt.result_payload->>'state_version')::bigint,
      (rcpt.result_payload->>'dispatch_revision')::bigint,
      (rcpt.result_payload->>'dispatch_id')::uuid,
      (rcpt.result_payload->>'queue_msg_id')::bigint,
      true;
    return;
  end if;

  select * into cfg from bug_ops.system_config where singleton=true;
  if bug_ops.queue_for_role(v_role) is null then raise exception 'INVALID_TARGET_ROLE'; end if;
  v_payload:=jsonb_build_object(
    'kind','ROUTE','home_project',cfg.project_key,'bug_id',p_bug_id,
    'expected_state_version',p_expected_state_version,'expected_dispatch_revision',p_expected_dispatch_revision,
    'target_role',v_role,'actor',p_actor,'reason',p_reason
  );
  v_digest:=bug_ops.sha256_jsonb(v_payload);

  select * into br from bug_ops.bug_reports b where b.bug_id=p_bug_id for update;
  if not found then raise exception 'BUG_NOT_FOUND'; end if;
  if br.state_version<>p_expected_state_version then raise exception 'STALE_STATE_VERSION expected %, actual %',p_expected_state_version,br.state_version; end if;
  if br.dispatch_revision<>p_expected_dispatch_revision then raise exception 'STALE_DISPATCH_REVISION expected %, actual %',p_expected_dispatch_revision,br.dispatch_revision; end if;
  if br.status='CLOSED' then raise exception 'BUG_CLOSED'; end if;

  v_state:=br.state_version+1;
  v_dispatch_rev:=br.dispatch_revision+1;
  v_routing:=br.routing_revision+1;
  v_snapshot:=jsonb_build_object(
    'dispatch_id',v_dispatch,'bug_id',p_bug_id,'home_project',br.home_project,'event_id',v_event,
    'state_version',v_state,'dispatch_revision',v_dispatch_rev,'target_role',v_role,
    'action','ROUTE','operation_id',p_operation_id
  );
  v_pdigest:=bug_ops.sha256_jsonb(v_snapshot);
  insert into bug_ops.bug_events(
    event_id,bug_id,state_version,routing_revision,dispatch_revision,event_type,actor,operation_id,
    request_digest,request_payload,details,dispatch_id,dispatch_snapshot,dispatch_payload_digest
  ) values(
    v_event,p_bug_id,v_state,v_routing,v_dispatch_rev,'ROUTED',p_actor,p_operation_id,v_digest,v_payload,
    jsonb_build_object('from_role',br.assigned_role,'to_role',v_role,'reason',p_reason),v_dispatch,v_snapshot,v_pdigest
  );
  select s into v_msg from pgmq.send('bug_dispatch',v_snapshot,0) s limit 1;
  insert into bug_ops.dispatch_events_v2(
    dispatch_id,queue_name,msg_id,event_type,bug_id,bug_event_id,target_role,payload_digest,observed_message
  ) values(v_dispatch,'bug_dispatch',v_msg,'ENQUEUED',p_bug_id,v_event,v_role,v_pdigest,v_snapshot);
  update bug_ops.bug_reports set assigned_role=v_role,state_version=v_state,routing_revision=v_routing,
    dispatch_revision=v_dispatch_rev,updated_at=clock_timestamp() where bug_id=p_bug_id;
  v_result:=jsonb_build_object(
    'bug_id',p_bug_id,'event_id',v_event,'state_version',v_state,'dispatch_revision',v_dispatch_rev,
    'dispatch_id',v_dispatch,'queue_msg_id',v_msg
  );
  v_result_digest:=bug_ops.sha256_jsonb(v_result);
  insert into bug_ops.operation_receipts(operation_id,request_digest,operation_kind,bug_id,controlling_event_id,result_payload,result_digest)
  values(p_operation_id,v_digest,'ROUTE',p_bug_id,v_event,v_result,v_result_digest);
  return query select p_bug_id,v_event,v_state,v_dispatch_rev,v_dispatch,v_msg,false;
end
$function$

CREATE OR REPLACE FUNCTION bug_ops.update_bug_status(p_operation_id uuid, p_bug_id uuid, p_expected_state_version bigint, p_status text, p_actor text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS TABLE(out_bug_id uuid, out_event_id uuid, out_state_version bigint, out_dispatch_revision bigint, idempotent_replay boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  br bug_ops.bug_reports%rowtype;
  cfg bug_ops.system_config%rowtype;
  rcpt bug_ops.operation_receipts%rowtype;
  v_requested text:=upper(btrim(p_status));
  v_current text;
  v_payload jsonb;
  v_digest text;
  v_event uuid:=gen_random_uuid();
  v_state bigint;
  v_dispatch_rev bigint;
  v_routing bigint;
  v_type text;
  v_role text;
  v_dispatch uuid;
  v_snapshot jsonb;
  v_pdigest text;
  v_msg bigint;
  v_result jsonb;
  v_result_digest text;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_operation_id::text,0));
  select * into cfg from bug_ops.system_config where singleton=true;
  v_payload:=jsonb_build_object(
    'kind','STATUS','home_project',cfg.project_key,'bug_id',p_bug_id,
    'expected_state_version',p_expected_state_version,'status',v_requested,'actor',p_actor,'note',p_note
  );
  v_digest:=bug_ops.sha256_jsonb(v_payload);

  select * into rcpt from bug_ops.operation_receipts r where r.operation_id=p_operation_id;
  if found then
    if rcpt.operation_kind<>'STATUS' or rcpt.request_digest<>v_digest then raise exception 'OPERATION_ID_REUSE_CONFLICT'; end if;
    return query select
      (rcpt.result_payload->>'bug_id')::uuid,
      (rcpt.result_payload->>'event_id')::uuid,
      (rcpt.result_payload->>'state_version')::bigint,
      (rcpt.result_payload->>'dispatch_revision')::bigint,
      true;
    return;
  end if;

  if v_requested not in ('NEW','TRIAGED','IN_PROGRESS','BLOCKED','FIXED','VERIFYING','CLOSED','REOPENED') then raise exception 'INVALID_STATUS'; end if;
  select * into br from bug_ops.bug_reports b where b.bug_id=p_bug_id for update;
  if not found then raise exception 'BUG_NOT_FOUND'; end if;
  if br.state_version<>p_expected_state_version then raise exception 'STALE_STATE_VERSION expected %, actual %',p_expected_state_version,br.state_version; end if;
  if v_requested='REOPENED' and br.status<>'CLOSED' then raise exception 'REOPEN_REQUIRES_CLOSED'; end if;
  if br.status='CLOSED' and v_requested<>'REOPENED' then raise exception 'BUG_CLOSED_REQUIRES_REOPEN'; end if;

  v_state:=br.state_version+1;

  if v_requested='REOPENED' then
    v_role:=cfg.coordinator_role;
    if bug_ops.queue_for_role(v_role) is null then raise exception 'COORDINATOR_ROLE_INELIGIBLE'; end if;
    v_dispatch_rev:=br.dispatch_revision+1;
    v_routing:=br.routing_revision + case when br.assigned_role is distinct from v_role then 1 else 0 end;
    v_dispatch:=gen_random_uuid();
    v_current:='NEW';
    v_type:='REOPENED';
    v_snapshot:=jsonb_build_object(
      'dispatch_id',v_dispatch,'bug_id',p_bug_id,'home_project',br.home_project,'event_id',v_event,
      'state_version',v_state,'dispatch_revision',v_dispatch_rev,'target_role',v_role,
      'action','BUG_REOPENED','operation_id',p_operation_id
    );
    v_pdigest:=bug_ops.sha256_jsonb(v_snapshot);
    insert into bug_ops.bug_events(
      event_id,bug_id,state_version,routing_revision,dispatch_revision,event_type,actor,operation_id,
      request_digest,request_payload,details,dispatch_id,dispatch_snapshot,dispatch_payload_digest
    ) values(
      v_event,p_bug_id,v_state,v_routing,v_dispatch_rev,v_type,p_actor,p_operation_id,v_digest,v_payload,
      jsonb_build_object('from_status',br.status,'to_status',v_current,'from_role',br.assigned_role,'to_role',v_role,'note',p_note),
      v_dispatch,v_snapshot,v_pdigest
    );
    select s into v_msg from pgmq.send('bug_dispatch',v_snapshot,0) s limit 1;
    insert into bug_ops.dispatch_events_v2(
      dispatch_id,queue_name,msg_id,event_type,bug_id,bug_event_id,target_role,payload_digest,observed_message
    ) values(v_dispatch,'bug_dispatch',v_msg,'ENQUEUED',p_bug_id,v_event,v_role,v_pdigest,v_snapshot);
    update bug_ops.bug_reports set status='NEW',assigned_role=v_role,state_version=v_state,
      routing_revision=v_routing,dispatch_revision=v_dispatch_rev,updated_at=clock_timestamp(),closed_at=null
      where bug_id=p_bug_id;
  else
    v_current:=v_requested;
    v_type:='STATUS_CHANGED';
    v_dispatch_rev:=br.dispatch_revision + case when v_current='CLOSED' then 1 else 0 end;
    v_routing:=br.routing_revision;
    update bug_ops.bug_reports set status=v_current,state_version=v_state,dispatch_revision=v_dispatch_rev,
      updated_at=clock_timestamp(),closed_at=case when v_current='CLOSED' then clock_timestamp() else null end
      where bug_id=p_bug_id;
    insert into bug_ops.bug_events(
      event_id,bug_id,state_version,routing_revision,dispatch_revision,event_type,actor,operation_id,
      request_digest,request_payload,details
    ) values(
      v_event,p_bug_id,v_state,v_routing,v_dispatch_rev,v_type,p_actor,p_operation_id,v_digest,v_payload,
      jsonb_build_object('from_status',br.status,'to_status',v_current,'note',p_note)
    );
  end if;

  v_result:=jsonb_build_object(
    'bug_id',p_bug_id,'event_id',v_event,'state_version',v_state,'dispatch_revision',v_dispatch_rev
  );
  v_result_digest:=bug_ops.sha256_jsonb(v_result);
  insert into bug_ops.operation_receipts(operation_id,request_digest,operation_kind,bug_id,controlling_event_id,result_payload,result_digest)
  values(p_operation_id,v_digest,'STATUS',p_bug_id,v_event,v_result,v_result_digest);
  return query select p_bug_id,v_event,v_state,v_dispatch_rev,false;
end $function$
